/* Painted relic icons (generated by tools/make_relicart.py from assets/relicart/*.png), keyed by relic base or
   legendary id. They are decoded at load; until one is ready the relic painter falls back to its glyph. */
const RELICART = {"whet":"data:image/webp;base64,","cog":"data:image/webp;base64,","glass":"data:image/webp;base64,","eye":"data:image/webp;base64,","brand":"data:image/webp;base64,","purse":"data:image/webp;base64,","spike":"data:image/webp;base64,","rime":"data:image/webp;base64,","fang":"data:image/webp;base64,","stud":"data:image/webp;base64,","totem":"data:image/webp;base64,","midas":"data:image/webp;base64,","prism":"data:image/webp;base64,","frostfire":"data:image/webp;base64,","chrono":"data:image/webp;base64,","overflow":"data:image/webp;base64,","ledger":"data:image/webp;base64,","barrow":"data:image/webp;base64,","idol":"data:image/webp;base64,","thunderfury":"data:image/webp;base64,","sunforge":"data:image/webp;base64,","storm":"data:image/webp;base64,","heartwood":"data:image/webp;base64,","phylactery":"data:image/webp;base64,"};
const RELIC_IMG = {};
for (const k in RELICART) { const im = new Image(); im.onload = () => { RELIC_IMG[k] = im; if (typeof onDirty === 'function') onDirty(); }; im.src = RELICART[k]; }
